def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    vals = [v for row in grid for v in row]
    bg = max(set(vals), key=vals.count)
    # A full straight 2-bar separates the canvas from an object. Extend a
    # parallel 8-bar just beyond the object's edge away from the separator.
    for r in range(h):
        if all(grid[r][c] == 2 for c in range(w)):
            above = [(i,j) for i in range(r) for j in range(w) if grid[i][j] != bg]
            below = [(i,j) for i in range(r+1,h) for j in range(w) if grid[i][j] != bg]
            if bool(above) == bool(below):
                continue
            obj = above if above else below
            rr = min(i for i,j in obj)-1 if above else max(i for i,j in obj)+1
            if 0 <= rr < h and all(grid[rr][c] == bg for c in range(w)):
                out[rr] = [8]*w
            return out
    for c in range(w):
        if all(grid[r][c] == 2 for r in range(h)):
            left = [(i,j) for i in range(h) for j in range(c) if grid[i][j] != bg]
            right = [(i,j) for i in range(h) for j in range(c+1,w) if grid[i][j] != bg]
            if bool(left) == bool(right):
                continue
            obj = left if left else right
            cc = min(j for i,j in obj)-1 if left else max(j for i,j in obj)+1
            if 0 <= cc < w and all(grid[i][cc] == bg for i in range(h)):
                for i in range(h): out[i][cc]=8
            return out
    return out
